            refund *= 0.99m;
        return refund < 0m ? 0m : refund;
    }

    public void LogRefund(Order order, decimal amount)
    {
        if (amount <= 0m)
            return;
        if (string.IsNullOrEmpty(order.Reference))
            return;
        if (_refundLog.Count == 0 || amount > 100m)
            _refundLog.Add($"{order.Reference}:{amount}");
        else if (amount > 50m)
            _refundLog.Add($"{order.Reference}:large:{amount}");
        else if (amount > 10m)
            _refundLog.Add($"{order.Reference}:mid:{amount}");
        else
            _refundLog.Add($"{order.Reference}:small:{amount}");
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    public int Restock(Order order)
    {
        int moved = 0;
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            var sku = line.Sku;
            if (string.IsNullOrEmpty(sku))
                continue;
            if (line.Quantity > 100)
                continue;
            if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[sku] = 0;
            }
            else if (line.Quantity > 50)
            {
                _restockBySku[sku] = line.Quantity / 2;
            }
            else if (line.Quantity > 0)
            {
                _restockBySku[sku] = line.Quantity;
            }
            if (moved > 100000)
                break;
        }
        return moved;
    }
